package checkout.pricing;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class DiscountPolicy {
    public static int totalCents(int unitCents, int quantity, boolean member) {
        if (unitCents < 0 || quantity < 0) {
            throw new IllegalArgumentException("unitCents and quantity must be non-negative");
        }
        if (quantity == 0) {
            return 0;
        }

        BigDecimal subtotal = BigDecimal.valueOf(unitCents).multiply(BigDecimal.valueOf(quantity));
        BigDecimal discountRate = member ? BigDecimal.valueOf(7) : BigDecimal.ZERO;
        if (quantity >= 12) {
            discountRate = discountRate.add(BigDecimal.valueOf(5));
        }

        BigDecimal multiplier = BigDecimal.ONE.subtract(discountRate.movePointLeft(2));
        BigDecimal total = subtotal.multiply(multiplier).setScale(0, RoundingMode.HALF_EVEN);

        if (total.compareTo(BigDecimal.valueOf(Integer.MAX_VALUE)) > 0) {
            throw new IllegalArgumentException("total exceeds Integer.MAX_VALUE");
        }
        return total.intValueExact();
    }
}
